$base = dirname(__DIR__, 2) . '/includes/'; require_once $base . 'SiteSettings/Layout/ResponsiveLayoutPolicy.php'; require_once $base . 'SiteSettings/Discovery/RuntimeControlResolver.php'; require_once $base . 'SiteSettings/Validation/ResponsiveFoundationValidator.php'; use CrescoLayer\SiteSettings\Layout\ResponsiveLayoutPolicy; use CrescoLayer\SiteSettings\Discovery\RuntimeControlResolver; use CrescoLayer\SiteSettings\Validation\ResponsiveFoundationValidator;
function v_assert(bool $ok, string $message): void { if (!$ok) { fwrite(STDERR, "FAIL: $message\n"); exit(1); } }
$controls=['active_breakpoints'=>['type'=>'select2'],'viewport_mobile'=>['type'=>'number'],'viewport_tablet'=>['type'=>'number'],'viewport_laptop'=>['type'=>'number'],'viewport_widescreen'=>['type'=>'number'],'container_width'=>['type'=>'slider','is_responsive'=>true,'size_units'=>['px','custom'],'range'=>['px'=>['min'=>300,'max'=>1500]]],'container_padding'=>['type'=>'dimensions','is_responsive'=>true,'size_units'=>['px','custom']]];
$spec=['settings'=>['layout'=>ResponsiveLayoutPolicy::layout_contract()]];$validator=new ResponsiveFoundationValidator(new RuntimeControlResolver($controls));$ok=$validator->validate($spec);v_assert(true===$ok['compatible'],'valid foundation compatible');v_assert(0===$ok['errorCount'],'no errors');v_assert('native-custom-unit-when-supported'===$ok['globalFluidStrategy'],'global fluid strategy reported');$broken=$spec;$broken['settings']['layout']['contentWidthPx']['widescreen']=1600;$bad=$validator->validate($broken);v_assert(false===$bad['compatible'],'range violation incompatible');v_assert(in_array('content_width_above_control_range',array_column($bad['errors'],'code'),true),'explicit range violation reported');$missing_controls=$controls;unset($missing_controls['viewport_widescreen']);$missing=(new ResponsiveFoundationValidator(new RuntimeControlResolver($missing_controls)))->validate($spec);v_assert(false===$missing['compatible'],'missing required Widescreen incompatible');v_assert(in_array('required_breakpoint_unsupported',array_column($missing['errors'],'code'),true),'missing breakpoint error');$padding=$spec;$padding['settings']['layout']['containerPadding']['desktop']=['fixedPx'=>0];$padding_result=$validator->validate($padding);v_assert(in_array('global_container_padding_not_fluid',array_column($padding_result['errors'],'code'),true),'zero global padding blocked');$no_custom=$controls;$no_custom['container_padding']['size_units']=['px'];$no_custom_result=(new ResponsiveFoundationValidator(new RuntimeControlResolver($no_custom)))->validate($spec);v_assert(true===$no_custom_result['compatible'],'older runtime remains compatible through explicit px fallback');v_assert(in_array('container_padding_custom_unit_unsupported',array_column($no_custom_result['warnings'],'code'),true),'custom unit fallback warning reported');echo "PASS: responsive foundation validator\n";
